from common import *
from publish_single_v2 import COMPARISON, selected_path, official, cell

if __name__=='__main__':
    save_source(__file__)
    assert all(v['status']=='completed' for v in read(PROGRESS)['scientific_candidates'].values())
    docs={v:read(selected_path(v)) for v in ['control_old',*COMPARISON]}
    summary=read(BASE/'docs/study-summary.json')
    values={v:{**cell(d),'rank_ic_mean':official(d)['h5']['rank_ic_mean']} for v,d in docs.items()}
    def ns(items):return [int(v.removeprefix('quantile')) for v in items]
    best={}
    adjacent={}
    for key in ['net_ann','net_sharpe','rank_ic_mean']:
        peak=max(values[v][key] for v in COMPARISON)
        best[key]={'n':ns([v for v in COMPARISON if values[v][key]==peak]),'value':peak,'old_continuous_control':values['control_old'][key],'difference_from_control':peak-values['control_old'][key]}
        adjacent[key]=[{'from_n':int(a[8:]),'to_n':int(b[8:]),'difference':values[b][key]-values[a][key]} for a,b in zip(COMPARISON,COMPARISON[1:])]
    windows={}
    for block,labels in [('head_years',[str(y) for y in range(2020,2027)]),('head_regimes',['D','F','T'])]:
        windows[block]={}
        for label in labels:
            segment={v:official(d)[block][label]['3']['5'] for v,d in docs.items()}
            windows[block][label]={'metrics':{v:{k:m[k] for k in ['n_days','net_ann','net_ann_vol','net_sharpe']} for v,m in segment.items()},'return_above_control_n':ns([v for v in COMPARISON if segment[v]['net_ann']>segment['control_old']['net_ann']]),'sharpe_above_control_n':ns([v for v in COMPARISON if segment[v]['net_sharpe']>segment['control_old']['net_sharpe']])}
    es=summary['early_stopping']
    out={'at':time.time(),'primary_label_source':'old','new_n':ns(VARIANTS),'reused_n':ns(REUSED),'tested_n':ns(COMPARISON),'best_tested_by_metric':best,'adjacent_differences':adjacent,'monotone_non_decreasing':{k:all(r['difference']>=0 for r in rows) for k,rows in adjacent.items()},'primary':values,'windows':windows,'seed_diagnostics':summary['seed_diagnostics'],'early_stop_flags':{'selected_round_le10':[r for r in es if r['best_iteration']<=10],'selected_boundary_ties':[r for r in es if any(r['selected_boundary_ties'].values())],'reverse_best_differs':[r for r in es if r['reverse_observed_best_differs']],'reverse_stop_not_observed':[r for r in es if r['reverse_stop_observed'] is None],'200_round_cap':[r for r in es if r['hit_200_round_cap']]},'sources':{v:fingerprint(selected_path(v)) for v in docs},'limitations':['Historical early-stopping/selection window; no independent OOS claim','Only one selected old-label sample; no new paired label-perturbation stability test','n7 uses already completed identical-input models; no second fit claimed','2020/2026 partial years; F style136 days in2024 only','Metric maxima describe this finite grid, not significance or promotion']}
    write(BASE/'docs/result-analysis.json',out)
    print(json.dumps({'best':best,'monotone':out['monotone_non_decreasing'],'flags':{k:len(v) for k,v in out['early_stop_flags'].items()}},ensure_ascii=False),flush=True)
